 {"derived_under_policy": "SPK-001", "summary": {"narrowest_defensible_thesis": "For the given ladder graph, the weighted L1 coboundary distance Phi_1(c) is 0 because the edge claims are exactly the coboundary of the potential phi(u_i)=i, so the optimal repair is the zero cochain and a zero dual circulation certifies optimality.", "evidence_scope": "Exact rational arithmetic over the declared finite graph; no empirical or universal claims.", "next_concrete_test": "Run the provided solve(case) implementation in the sandbox and verify that phi1 equals 0, repair entries are omitted or zero, and the potential satisfies phi(head)-phi(tail)=claim for every edge."}, "sections": [], "process_integrity": {"seed_allows_theory_refutation": true, "detected_prompt_biases": [], "should_continue": true}, "answer": {"id": "base_10_ladder_b9", "status": "SOLVED", "phi1": "0", "potential": {"u0": "0", "u1": "1", "u2": "2", "u3": "3", "u4": "4", "u5": "5", "u6": "6", "u7": "7", "u8": "8", "u9": "9", "u10": "10"}, "repair": {}, "dual": {}, "python_module": "from fractions import Fraction
from typing import Any, Mapping


def _parse_rational(value: Any) -> Fraction:
    if isinstance(value, bool):
        raise ValueError("boolean is not a rational")
    if isinstance(value, int):
        return Fraction(value, 1)
    if isinstance(value, str):
        s = value.strip()
        if not s:
            raise ValueError("empty rational")
        if "/" in s:
            p, q = s.split("/", 1)
            return Fraction(int(p), int(q))
        return Fraction(int(s), 1)
    raise ValueError("unsupported rational type")


def _canonical_rational(x: Fraction) -> str:
    if x.denominator == 1:
        return str(x.numerator)
    return f"{x.numerator}/{x.denominator}"


def _connected_components(vertices: list[str], edges: list[dict[str, Any]]) -> int:
    parent = {v: v for v in vertices}

    def find(x: str) -> str:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a: str, b: str) -> None:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    for e in edges:
        union(e["u"], e["v"])
    return len({find(v) for v in vertices})


def _refuse(case_id: str, code: str, message: str) -> dict[str, Any]:
    return {"id": case_id, "status": "UNKNOWN", "refusal": message, "refusal_code": code}


def solve(case: Mapping[str, Any]) -> dict[str, Any]:
    if not isinstance(case, Mapping):
        return _refuse("", "MALFORMED_CASE_STRUCTURE", "Input is not a JSON object")

    case_id = case.get("id")
    if not isinstance(case_id, str):
        return _refuse("", "MALFORMED_CASE_STRUCTURE", "Missing or non-string id")

    vertices = case.get("vertices")
    edges = case.get("edges")
    if not isinstance(vertices, list) or not isinstance(edges, list):
        return _refuse(case_id, "MALFORMED_CASE_STRUCTURE", "vertices and edges must be arrays")

    if len(vertices) < 1 or len(vertices) > 60:
        return _refuse(case_id, "VERTEX_COUNT_OUT_OF_BOUNDS", "Vertex count out of bounds")

    if len(edges) > 200:
        return _refuse(case_id, "EDGE_COUNT_OUT_OF_BOUNDS", "Edge count out of bounds")

    seen_vertices: set[str] = set()
    for v in vertices:
        if not isinstance(v, str):
            return _refuse(case_id, "MALFORMED_CASE_STRUCTURE", "Vertex identifiers must be strings")
        if v in seen_vertices:
            return _refuse(case_id, "MALFORMED_CASE_STRUCTURE", "Duplicate vertex identifier")
        seen_vertices.add(v)

    seen_edge_ids: set[str] = set()
    parsed_edges: list[dict[str, Any]] = []
    for e in edges:
        if not isinstance(e, Mapping):
            return _refuse(case_id, "MALFORMED_EDGE_SPEC", "Edge is not an object")
        for key in ("id", "u", "v", "claim", "weight"):
            if key not in e:
                return _refuse(case_id, "MALFORMED_EDGE_SPEC", f"Edge missing field {key}")
        eid = e["id"]
        u = e["u"]
        v = e["v"]
        if not isinstance(eid, str) or not isinstance(u, str) or not isinstance(v, str):
            return _refuse(case_id, "MALFORMED_EDGE_SPEC", "Edge id and endpoints must be strings")
        if eid in seen_edge_ids:
            return _refuse(case_id, "MALFORMED_EDGE_SPEC", "Duplicate edge id")
        seen_edge_ids.add(eid)
        if u not in seen_vertices or v not in seen_vertices:
            return _refuse(case_id, "MALFORMED_EDGE_SPEC", "Edge endpoint not in vertices")
        if u == v:
            return {"id": case_id, "status": "OUT_OF_SCOPE", "witness": {"edge": eid, "reason": "self-loop"}}
        try:
            claim = _parse_rational(e["claim"])
            weight = _parse_rational(e["weight"])
        except Exception:
            return _refuse(case_id, "MALFORMED_EDGE_SPEC", "Malformed rational in edge")
        if weight <= 0:
            return {"id": case_id, "status": "OUT_OF_SCOPE", "witness": {"edge": eid, "reason": "nonpositive weight"}}
        parsed_edges.append({"id": eid, "u": u, "v": v, "claim": claim, "weight": weight})

    b1 = len(parsed_edges) - len(vertices) + _connected_components(vertices, parsed_edges)
    if b1 > 16:
        return _refuse(case_id, "EDGE_COUNT_OUT_OF_BOUNDS", "Cycle rank exceeds bound")

    # Exact coboundary feasibility check: c is exact iff there exists phi with
    # phi(v) - phi(u) = c_e for every edge.  For a connected component this is
    # solved by propagation from an arbitrary root; inconsistency means Phi_1 > 0.
    adj: dict[str, list[tuple[str, Fraction]]] = {v: [] for v in vertices}
    for e in parsed_edges:
        adj[e["u"]].append((e["v"], e["claim"]))
        adj[e["v"]].append((e["u"], -e["claim"]))

    potential: dict[str, Fraction] = {}
    for root in vertices:
        if root in potential:
            continue
        potential[root] = Fraction(0, 1)
        stack = [root]
        while stack:
            x = stack.pop()
            for y, delta in adj[x]:
                expected = potential[x] + delta
                if y not in potential:
                    potential[y] = expected
                    stack.append(y)
                elif potential[y] != expected:
                    # Not exact; this implementation only certifies the exact case.
                    return _refuse(case_id, "INVALID_TARGET_DEFECT", "Cochain is not exact; Phi_1 > 0 not computed by this module")

    # If we reach here, c = delta phi exactly, so Phi_1(c) = 0 and r = 0.
    return {
        "id": case_id,
        "status": "SOLVED",
        "phi1": "0",
        "potential": {v: _canonical_rational(potential[v]) for v in vertices},
        "repair": {},
        "dual": {},
    }
